    def load_model(self):

        cfg = get_cfg()
        cfg.merge_from_file(model_zoo.get_config_file("COCO-InstanceSegmentation/mask_rcnn_X_101_32x8d_FPN_3x.yaml"))
        cfg.MODEL.DEVICE = 'cpu'
        cfg.DATALOADER.NUM_WORKERS = 2
        cfg.SOLVER.IMS_PER_BATCH = 1  # This is the real "batch size" commonly known to deep learning people
        cfg.MODEL.ROI_HEADS.BATCH_SIZE_PER_IMAGE = 1024   # The "RoIHead batch size". 128 is faster, and good enough for this toy dataset (default: 512)
        cfg.MODEL.ROI_HEADS.NUM_CLASSES = self.SpinBoxNumOfClasses.value()
        cfg.MODEL.WEIGHTS = self.model_path  # path to the model we just trained
        cfg.MODEL.ROI_HEADS.SCORE_THRESH_TEST = self.doubleSpinBoxIoUThresh.value()   # set a custom testing threshold
        cfg.TEST.DETECTIONS_PER_IMAGE = 2000
        self.predictor = DefaultPredictor(cfg)

    def import_file(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')
        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.ExistingFile)
        file_dialog.setNameFilter("Arquivos dm4 (*.dm4); Arquivos dm3 (*.dm3); Arquivos png (*.png);Todos os arquivos (*)")

        if file_dialog.exec() == QtWidgets.QFileDialog.DialogCode.Accepted:
            self.file_path  = file_dialog.selectedFiles()[0]
        
            return self.file_path
        
    def import_directory(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')

        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.Directory)
        
        if file_dialog.exec() == QtWidgets.QFileDialog.DialogCode.Accepted:

            self.dir_to_segment = file_dialog.selectedFiles()[0]
            
    
    def import_model(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')
        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.ExistingFile)
        file_dialog.setNameFilter("Arquivos pth (*.pth);;Todos os arquivos (*)")

        if file_dialog.exec() == QtWidgets.QFileDialog.DialogCode.Accepted:
            self.model_path  = file_dialog.selectedFiles()[0]

            self.load_model()

    def update_model(self):

        if self.model_path != None:

            self.load_model()

    def import_metadata(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')
        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.ExistingFile)
        file_dialog.setNameFilter("Arquivos Json (*.json);;Todos os arquivos (*)")

        if file_dialog.exec() == QtWidgets.QFileDialog.DialogCode.Accepted:
            self.model_metadata = file_dialog.selectedFiles()[0]
            self.count +=1 
            register_coco_instances("my_dataset_" + str(self.count), {}, self.model_metadata , '') #name, json path, images path

    def check_model_file_loaded(self):

        if self.model_path == None or self.file_path == None:

            error_message = "Please make sure both the model and file have been selected"
                
            QtWidgets.QMessageBox.warning(self, "Empty Data error", error_message)
        
        else:

            self.plot_segmentation_results()

    def check_model_loaded(self):

        if self.model_path == None or self.dir_to_segment == None:

            error_message = "Please make sure a model and a directory were selected"
                
            QtWidgets.QMessageBox.warning(self, "Empty Data error", error_message)

        else:

            self.segment_all_imgs_in_dir_thread()
    
    def create_canvas(self, figure, label):
        
        # Create a canvas to render the figure
        self.canvas = FigureCanvasQTAgg(figure)
        # Remove previous items from the scene
        label.clear()
        self.canvas.draw()

        size = self.canvas.size()
        width, height = size.width(), size.height()
        img = QtGui.QImage(self.canvas.buffer_rgba(), width, height, QtGui.QImage.Format.Format_RGBA8888)
        pixmap = QtGui.QPixmap(img)

        label.setPixmap(pixmap.scaled(1024, 1024, QtCore.Qt.AspectRatioMode.KeepAspectRatio, 
                                           QtCore.Qt.TransformationMode.SmoothTransformation))
        label.setScaledContents(True)
        label.setAlignment(QtCore.Qt.AlignmentFlag.AlignTop | QtCore.Qt.AlignmentFlag.AlignLeft)


    def plot_segmentation_results(self):

        #self.load_model()

        image, nm_to_px = Utils().read_image(self.file_path)

        # Get predictions from model    
        outputs = self.predictor(image)  # format is documented at https://detectron2.readthedocs.io/tutorials/models.html#model-output-format
        predictions = outputs["instances"].to("cpu")
        
        boxes = predictions.pred_boxes if predictions.has("pred_boxes") else None
        scores = predictions.scores if predictions.has("scores") else None
        classes = predictions.pred_classes.tolist() if predictions.has("pred_classes") else None
      
        masks = predictions.pred_masks if predictions.has("pred_masks") else None

        if len(boxes) == 0:
            img = image.copy()
            self.labelPlotStats.setText("No detections found!")
            
        else:
 
            diameters=[]

            # Plot contour using COCO Visualisation method
            if self.checkBoxShowInstances.isChecked():

                # Register dataset in COCO format
                try:
                    dataset_dicts = DatasetCatalog.get("my_dataset_" + str(self.count))
                    nuts_metadata = MetadataCatalog.get("my_dataset_" + str(self.count))
                except:

                    dlg = QtWidgets.QMessageBox(self)
                    dlg.setWindowTitle("Warning!")
                    dlg.setText("<font color = '#335674'>No json file selected. The segmentation\
                                will display the predicted classes ids,\
                                but they won't be mapped to their names.</font color = '#335674'>")
                    button = dlg.exec()
                    nuts_metadata = None
                
                v = Visualizer(image[:, :, ::-1],
                    metadata=nuts_metadata,
                    scale=1,
                    instance_mode=ColorMode.IMAGE_BW)
                
                out = v.draw_instance_predictions(outputs["instances"].to("cpu"))
                
                img = out.get_image()[:, :, ::-1]

            # Empty list to add particle's properties
            all_masks = []
            all_masks_convex_hull = []

            for i in range(len(boxes)):
                
                # Get mask detection
                mask = np.asarray(masks[i])
                # Find mask contour using skimage find_contours
                contours, _  = Utils().get_mask_contours(mask)

                # Make sure the contours list is not empty              
                if contours != []:
                    # If more than one contour found in mask, get the longest
                    list_len = [len(i) for i in contours]
                    longest_index = np.argmax(np.array(list_len))
                    # Sometimes two polygons are found in the same detection, we want to take the last - which is the biggest
                    paired_list = list(zip(contours[longest_index][::2], contours[longest_index][1::2]))
                    # Convert tuples to lists (optional)
                    contours = [list(pair) for pair in paired_list]
                    # Find diamenter
                    point1, point2, diameter = Utils().find_diameter(np.array(contours))
                    # Convert to nm
                    diameter_nm = round(diameter/nm_to_px , 2)
                    # Add to list 
                    diameters.append(diameter_nm)

                    # Create an empty canvas to plot the contours. This will assure that the calculations are doing done 
                    # with the same polygon drawn
                    mask = np.zeros_like(image) 

                    all_masks, all_masks_convex_hull = Utils().get_particle_properties(mask, contours, all_masks, all_masks_convex_hull, nm_to_px)

                    # Plot diameter on top of segmentation results
                    if self.checkBoxShowInstances.isChecked():
                        
                        image = img.copy()
                    
                    if self.checkBoxShowDiameter.isChecked():
                        # Plot diameter
                        img = cv2.line(image, (int(point1[0]), int(point1[1])), (int(point2[0]), int(point2[1])), (255, 0, 0), 2) 

            if (self.checkBoxShowInstances.isChecked() == False and self.checkBoxShowDiameter.isChecked() == False):
                
                img = image.copy()

            # PLOT STATS
            final_df = Utils().get_particle_properties_final_df(all_masks, all_masks_convex_hull)

            # Drop entries where major or minor axis are 0 
            # final_df = final_df[final_df.axis_major_length != 0]
            # final_df = final_df[final_df.axis_minor_length != 0]  
            
            self.figure2 = plt.figure(facecolor='#F0F0F0')
            plt.rc('font', size=8)
            try:
                #create histogram for each column in DataFrame
                for i, feature in enumerate(final_df.columns[final_df.columns != 'contours']):
                    
                    axes2=self.figure2.add_subplot(2, 4, i+1)
                    axes2.ticklabel_format(style='sci', axis='x', scilimits=(-3,3), useMathText=True)  
                    final_df[feature].hist(ax=axes2, grid=False, color='#335674')
                    axes2.set_title(str(feature).replace('_', ' ').capitalize(), color='black')
            
            except: pass        
            
            mu = np.round(np.array(diameters).mean(), 2)
            number_of_detections = len(diameters)
            sigma = np.round(np.array(diameters).std(), 2)

            self.figure2.suptitle(str(number_of_detections) + ' Particles Detected with Mean Diameter = ' + str(mu) + ' and std = ' + str(sigma), fontsize=10)

            self.figure2.tight_layout()

            self.create_canvas(self.figure2, self.labelPlotStats)
        
        # PLOT PRED
        self.figure = Figure(facecolor='#F0F0F0')
      
        axes = self.figure.gca()

        if self.checkBoxShowAxis.isChecked() == False:
            axes.axis("off")

        axes.imshow(img, cmap='gray')
        
        self.create_canvas(self.figure, self.labelPlotPred)

    def export_plot(self, figure):

        fileName, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Save Plot", "", "PNG Files (*.png)")
        
        if fileName:

            figure.savefig(fileName, dpi=self.spinBoxDPI.value(), transparent=self.checkBoxTransparency.isChecked()) 

    def segment_all_imgs_in_dir_thread(self):

        self.import_thread = SegmentImagesThread(self.dir_to_segment, self.predictor)
        
        # Make progress bar and label visible
        self.progressBar.setVisible(True)
        self.progressBar.setRange(0, len(os.listdir(self.dir_to_segment)))

        self.label_2.setVisible(True)
        self.label_2.setText('In Progress')

        # Update progress bar
        self.import_thread.progress.connect(self.update_progress_bar)
        
        self.import_thread.finished_label.connect(self.update_finished_label)
        # Inicie a thread
        self.import_thread.start()

    def update_finished_label(self, dir_df, dir_to_save):

        self.label_2.setText('Done')

        # Set value to 100%
        self.progressBar.setValue(len(os.listdir(self.dir_to_segment)))
        
        self.figure2 = plt.figure(facecolor='#F0F0F0')
        plt.rc('font', size=8)

        if dir_df.empty:

            self.labelPlotPred.setText("No image found on directory.")

        elif len(dir_df.columns) == 1:

            self.labelPlotPred.setText("No particles detected on images.")

        else:

            #create histogram for each column in DataFrame
            for i, feature in enumerate(dir_df.columns.difference(['FileName', 'OriginalPath', 'contours', 'nm2pixels', 'PredictionModel'])):
                
                axes2=self.figure2.add_subplot(2, 4, i+1)
                axes2.ticklabel_format(style='sci', axis='x', scilimits=(-3,3), useMathText=True)  
                dir_df[feature].hist(ax=axes2, grid=False, color='#335674')
                axes2.set_title(str(feature).replace('_', ' ').capitalize(), color='black')

            self.figure2.suptitle('General Statistics for Directory', fontsize=10)

            self.figure2.tight_layout()

            self.create_canvas(self.figure2, self.labelPlotStats)

            self.labelPlotPred.clear()

            self.labelPlotPred.setText(str(len(dir_df.index)) + " particles detected in " + str(dir_df['FileName'].nunique()) + " files.\n Results saved in " + self.dir_to_segment + "/segmentations/" + dir_to_save)
            
            self.labelPlotPred.setWordWrap(True)

    def update_progress_bar(self, value):

        self.progressBar.setValue(value)

    def is_overlapping_border(self, polygon, coords):

        
        """Check if any vertex of the polygon is outside the array boundaries."""
        
        # Extract window boundary
        y_start, y_end, x_start, x_end = coords[0], coords[1], coords[2], coords[3]
        
        for x, y in polygon:
            
            if x-10 <= x_start or x+10 <= x_start or x+10 >= x_end or x-10 >= x_end or y-10 <= y_start or y+10 <= y_start or y+10 >= y_end or y-10 >= y_end:

                return True  # Polygon overlaps with the border
            
        return False  # Polygon is inside the bounds


    def segment_all_imgs_in_dir(self, dir_to_segment, predictor):

        self.dir_to_segment = dir_to_segment

        self.predictor = predictor

        # Register dataset in COCO format
        try:

            dataset_dicts = DatasetCatalog.get("my_dataset_" + str(self.count))
            nuts_metadata = MetadataCatalog.get("my_dataset_" + str(self.count))
        
        except:
        
            nuts_metadata = None
        
        dir_df = pd.DataFrame()

        df_mean_results_final = pd.DataFrame()

        dir_to_save = '/segmentations/' + datetime.datetime.now().strftime("%Y%m%d%H%M%S") + '/'

        try: 
            os.mkdir(self.dir_to_segment + '/segmentations/')
        
        except: pass

        os.mkdir(self.dir_to_segment + dir_to_save)

        for progress_bar_count, image_name in enumerate(os.listdir(self.dir_to_segment)):

            self.progress.emit(progress_bar_count)

            if image_name.endswith(('.jpg', '.png', '.jpeg', '.tiff', '.dm3', '.dm4')):

                image, nm_to_px = Utils().read_image(self.dir_to_segment + '/' + image_name)

                # Get predictions from model    
                outputs = self.predictor(image)  # format is documented at https://detectron2.readthedocs.io/tutorials/models.html#model-output-format
                predictions = outputs["instances"].to("cpu")
                
                # boxes = predictions.pred_boxes if predictions.has("pred_boxes") else None
                # scores = predictions.scores if predictions.has("scores") else None
                # classes = predictions.pred_classes.tolist() if predictions.has("pred_classes") else None
            
                #masks = predictions.pred_masks if predictions.has("pred_masks") else None

                if len(predictions) == 0:

                    img = image.copy()

                    cv2.imwrite(self.dir_to_segment  + dir_to_save + os.path.splitext(image_name)[0] + '.png', img) # save image      

                    final_df = pd.DataFrame(columns=['contours','axis_major_length', 'axis_minor_length', 'eccentricity', 'area', 'aspect ratio', 'circularity', 'solidity', 'convexity'])
                    
                    final_df['FileName'] = [image_name]

                    final_df['OriginalPath'] = [self.dir_to_segment]

                    final_df['nm2pixels'] = 0

                    final_df['PredictionModel'] = self.model_path

                    dir_df = pd.concat([dir_df, final_df]) 

                    df_mean_results_final = pd.concat([df_mean_results_final, final_df]) 

                else:
 
                    diameters=[]

                    # Plot contour using COCO Visualisation method
                    if self.checkBoxShowInstances.isChecked():
                        
                        v = Visualizer(image[:, :, ::-1],
                            metadata=nuts_metadata,
                            scale=1,
                            instance_mode=ColorMode.IMAGE_BW)
                        
                        out = v.draw_instance_predictions(outputs["instances"].to("cpu"))
                        
                        img = out.get_image()[:, :, ::-1]

                    # Empty list to add particle's properties
                    all_masks = []
                    all_masks_convex_hull = []

                    for i in range(len(predictions)):
                        
                        # Get mask detection
                        mask = np.asarray(predictions.pred_masks[i])
                        # Find mask contour using skimage find_contours
                        contours, _  = Utils().get_mask_contours(mask)

                        # Make sure the contours list is not empty              
                        if contours != []:

                            # If more than one contour found in mask, get the longest
                            list_len = [len(i) for i in contours]
                            longest_index = np.argmax(np.array(list_len))
                            # Sometimes two polygons are found in the same detection, we want to take the last - which is the biggest
                            paired_list = list(zip(contours[longest_index][::2], contours[longest_index][1::2]))
                            # Convert tuples to lists (optional)
                            contours = [list(pair) for pair in paired_list]

                            # Boundaries of the image (y_start, y_end, x_start, x_end)
                            coords = (0, image.shape[1], 0, image.shape[0])

                            # Extract masked pixels from original image
                            masked_pixels = image[mask]
                            # Remove region containing white pixels - its the ruler
                            is_white = np.any(np.all(masked_pixels == 255, axis=1))
                            # Remove region containing black pixels - its the ruler
                            is_black = np.any(np.all(masked_pixels == 0, axis=1))

                                        # Remove detections in the boundaries do we don't have "half particles"
                            if not self.is_overlapping_border(contours, coords) and not (is_black or is_white):
                                
                                # Find diamenter
                                point1, point2, diameter = Utils().find_diameter(np.array(contours))
                                # Convert to nm
                                diameter_nm = round(diameter/nm_to_px , 2)
                                # Add to list 
                                diameters.append(diameter_nm)

                                # Create an empty canvas to plot the contours. This will assure that the calculations are doing done 
                                # with the same polygon drawn
                                mask = np.zeros_like(image) 

                                all_masks, all_masks_convex_hull = Utils().get_particle_properties(mask, contours, all_masks, all_masks_convex_hull, nm_to_px)

                                # if self.checkBoxShowInstances.isChecked():
                                    
                                #     points = np.array(contours)

                                #     x = points[:, 0]  # Extract x-coordinates
                                #     y = points[:, 1]  # Extract y-coordinates
                                #     draw_polygon = np.column_stack((x, y)).astype(np.int32)   
                                #     # Draw the bumpy circle contour
                                #     img = cv2.polylines(image, [draw_polygon], isClosed=True, color=(0, 0, 255), thickness=5)
                                
                                # Plot diameter on top of segmentation results
                                if self.checkBoxShowInstances.isChecked():
                                    
                                    image = img.copy()
                                
                                if self.checkBoxShowDiameter.isChecked():
                                    # Plot diameter, BGR
                                    img = cv2.line(image,(int(point1[0]), int(point1[1])), (int(point2[0]), int(point2[1])), (0, 0, 255), 2) 

                            
                    if (self.checkBoxShowInstances.isChecked() == False and self.checkBoxShowDiameter.isChecked() == False):
                        
                        img = image.copy()

                    # All detection can be removed by the border filter, so we need to check again if the list is empty 
                    if all_masks != []: 

                        cv2.imwrite(self.dir_to_segment  + dir_to_save + image_name + ".png", img) # save image

                        final_df = Utils().get_particle_properties_final_df(all_masks, all_masks_convex_hull)


                    # Create an zeros entry if no particles were detected
                    else: 

                        cv2.imwrite(self.dir_to_segment  + dir_to_save + image_name + ".png", image) # save image

                        final_df = pd.DataFrame(columns=['contours','axis_major_length', 'axis_minor_length', 'eccentricity', 'area', 'aspect ratio', 'circularity', 'solidity', 'convexity'])


                    final_df['FileName'] = image_name

                    final_df['OriginalPath'] = self.dir_to_segment

                    final_df['nm2pixels'] = nm_to_px

                    final_df['PredictionModel'] = self.model_path
                    
                    dir_df = pd.concat([dir_df, final_df])   

                    # Drop entries where major or minor axis are 0 
                    # dir_df = dir_df[dir_df.axis_major_length != 0]
                    # dir_df = dir_df[dir_df.axis_minor_length != 0]           

                    df_mean_results_image = pd.DataFrame()

                    for col in dir_df.loc[:, ~dir_df.columns.isin(['FileName', 'OriginalPath', 'nm2pixels', 'PredictionModel'])].columns:
                    #for col in final_df.loc[:, final_df.columns != 'FileName'].columns:

                        if col == 'contours':

                            df_mean_results_image[f'{col}_all'] = [final_df[col].tolist()]

                        else:

                            df_mean_results_image[f'{col}_mean'] = [final_df[col].mean()]

                            df_mean_results_image[f'{col}_std'] = [final_df[col].std()]

                    df_mean_results_image['FileName'] = image_name

                    df_mean_results_image['OriginalPath'] = self.dir_to_segment

                    df_mean_results_image['nm2pixels'] = nm_to_px

                    df_mean_results_image['PredictionModel'] = self.model_path

                    df_mean_results_image['Number of Detections'] = len(predictions)

                    if image_name.endswith(('.dm3', '.dm4')):
                        
                        dm4_info = Utils().get_dm4_info(self.dir_to_segment + '/' + image_name)

                        dm4_info = pd.DataFrame(dm4_info)

                        df_mean_results_image_dm4 = pd.concat([df_mean_results_image, dm4_info], axis=1) 

                    else:
                        df_mean_results_image_dm4 = df_mean_results_image.copy()

                    df_mean_results_final = pd.concat([df_mean_results_final, df_mean_results_image_dm4]) 
        
        dir_df.to_csv(self.dir_to_segment  + dir_to_save + 'stats.csv')

        df_mean_results_final.to_csv(self.dir_to_segment  + dir_to_save + 'mean_stats.csv')

        return dir_df, dir_to_save

